// ═══════════════════════════════════════════════════════
// GLOBAL CONFIG — заміна n8n Variables (Starter plan)
// Заповни свої ключі тут. Всі інші вузли посилаються на
// $('Global Config').item.json.XXXX
// ═══════════════════════════════════════════════════════
return [{ json: {
  GEMINI_API_KEY:       'YOUR_GEMINI_API_KEY',
  SUPABASE_URL:         'https://nexkairsedqtczievxpa.supabase.co',
  SUPABASE_SERVICE_KEY: 'YOUR_SUPABASE_SERVICE_ROLE_KEY'
}}];

const body = $json.body || $json;
const { service_slug, user_id, answers } = body;

if (!user_id) return [{ json: { _valid: false, _error: 'missing user_id' } }];
if (!service_slug) return [{ json: { _valid: false, _error: 'missing service_slug' } }];
if (!answers || Object.keys(answers).length === 0) return [{ json: { _valid: false, _error: 'empty answers' } }];

return [{ json: {
  _valid: true,
  _user_id: String(user_id),
  _service_slug: service_slug,
  _answers: answers,
  _submitted_at: new Date().toISOString()
}}];

// =============================================================
// RAG STEP 1: Будуємо пошуковий запит з відповідей форми
// Чим точніший запит — тим релевантніший контекст отримаємо
// =============================================================
const answers = $('Validate').item.json._answers || {};
const serviceSlug = $('Validate').item.json._service_slug;

const terms = [];

// Базовий контекст по послузі
if (serviceSlug === 'divorce') {
  terms.push('розірвання шлюбу підстави порядок');
}

// Контекстні уточнення за відповідями
if (answers.has_children === true || answers.has_children === 'true') {
  terms.push('місце проживання дітей після розлучення аліменти на дитину');
}
if (answers.alimony_claim === true || answers.alimony_claim === 'true') {
  terms.push('стягнення аліментів розмір аліментів');
}
if (answers.has_joint_property === true || answers.has_joint_property === 'true') {
  terms.push('поділ спільного майна подружжя');
}
if (answers.debt_claim === true || answers.debt_claim === 'true') {
  terms.push('спільні боргові зобовязання');
}

// Завжди додаємо процесуальний контекст
terms.push('позовна заява до суду судовий збір');

const queryText = terms.join(' ');
console.log('[RAG] Query:', queryText);

return [{ json: { query_text: queryText, service_slug: serviceSlug } }];

