// =============================================================
// Формуємо запит до Groq з RAG-контекстом
// ai_prompt береться з Supabase services.ai_prompt (від юриста)
// Якщо порожній — використовуємо дефолтний промпт
// =============================================================

const answers = $('Validate').item.json._answers || {};
const service = $('Get Service').item.json;
const caseId = $('Insert Case').item.json.id;
const today = new Date().toLocaleDateString('uk-UA', {day:'2-digit', month:'2-digit', year:'numeric'});

// RAG: отримуємо знайдені статті
const rawChunks = $json;
const lawChunks = Array.isArray(rawChunks) ? rawChunks : [];

// Форматуємо правовий контекст
let lawContext = '';
if (lawChunks.length > 0) {
  lawContext = '\n\n=== ПРАВОВА БАЗА (релевантні статті, знайдені через RAG) ===\n';
  for (const chunk of lawChunks) {
    lawContext += `\n📖 ${chunk.law_title}, Стаття ${chunk.article_num}`;
    if (chunk.article_title) lawContext += ` — ${chunk.article_title}`;
    lawContext += ` [${chunk.match_type}, score: ${(chunk.similarity || 0).toFixed(3)}]:\n`;
    lawContext += (chunk.full_content || '').trim() + '\n';
  }
  lawContext += '\n=== КІНЕЦЬ ПРАВОВОЇ БАЗИ ===\n';
  lawContext += '\nВИКОРИСТАЙ ці статті для правового обґрунтування. Посилайся на них у документі ("На підставі ст. X Сімейного кодексу України...").';
} else {
  lawContext = '\n\n[Примітка: правова база недоступна, складай документ на основі загальних знань]';
}

// ai_prompt від юриста (з Supabase) або дефолтний
const defaultPrompt = `Ти — досвідчений юрист-практик, спеціалізуєшся на сімейному праві України. Склади офіційну ПОЗОВНУ ЗАЯВУ про розірвання шлюбу на підставі даних клієнта.

СТРОГА СТРУКТУРА ДОКУМЕНТА:

До [назва суду за місцем проживання відповідача]
(Знайти ваш суд: https://court.gov.ua/)

Позивач: [ПІБ позивача у Н.в.]
Адреса: [адреса]
Тел.: [телефон, якщо вказано]

Відповідач: [ПІБ відповідача у Н.в.]
Адреса: [адреса відповідача, якщо вказана]

ПОЗОВНА ЗАЯВА
про розірвання шлюбу

[ДАТА реєстрації шлюбу] між мною, [ПІБ позивача], та [ПІБ відповідача], було зареєстровано шлюб у [місце реєстрації].

[ЯКЩО has_children = true]: Від шлюбу народились спільні неповнолітні діти: [список дітей з датами народження]

Спільне подружнє та сімейне життя між нами не склалося. Шлюбні відносини фактично припинились, примирення неможливе.

[ЯКЩО has_joint_property = true]: Між нами наявне спільне майно: [перелік].

На підставі статей Сімейного кодексу України та ЦПК України (точні посилання — з правової бази вище),

ПРОШУ:
1. Розірвати шлюб між [ПІБ позивача у Р.в.] та [ПІБ відповідача у Р.в.], зареєстрований [дата] у [місце].
[ЯКЩО has_children = true і children_with = 'me']: 2. Визначити місце проживання [ПІБ дітей] зі мною.
[ЯКЩО alimony_claim = true]: [номер]. Стягнути аліменти у розмірі [25%/33%/50%] від доходу.

ПЕРЕЛІК ДОДАНИХ ДОКУМЕНТІВ:
1. Копія паспорта позивача — 2 прим.
2. Копія свідоцтва про шлюб — 2 прим.
[ЯКЩО has_children = true]: 3. Копії свідоцтв про народження — [кількість] прим.
4. Квитанція про сплату судового збору — 1 прим.

[ПІБ позивача] _______________   ${today}

ПРАВИЛА:
- Мова: виключно українська, офіційно-діловий стиль
- Суд: НЕ вказуй назву, тільки посилання на court.gov.ua
- Якщо поле не заповнено — пропусти рядок без заглушок`;

const basePrompt = (service.ai_prompt && service.ai_prompt.trim().length > 50)
  ? service.ai_prompt
  : defaultPrompt;

const systemPrompt = basePrompt + lawContext;

const userContent = `Дані клієнта (JSON-анкета):\n${JSON.stringify(answers, null, 2)}\n\nПослуга: ${service.title || 'Розірвання шлюбу'}\nКейс №: ${caseId}\nПоточна дата: ${today}\nРелевантних статей знайдено: ${lawChunks.length}`;

console.log('[RAG] Знайдено статей:', lawChunks.length);
console.log('[RAG] Джерела:', lawChunks.map(c => `Ст.${c.article_num} ${c.law_title} (${c.match_type})`).join(', '));
console.log('[Prompt] Використано ai_prompt:', !!(service.ai_prompt && service.ai_prompt.trim().length > 50));

return [{
  json: {
    model: 'llama-3.3-70b-versatile',
    max_tokens: 3500,
    temperature: 0.15,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userContent }
    ]
  }
}];

